def generated_loss(batch, model_output, extra):
    # Required preference logits (winner/loser). Keep expects strict to pass static gates.
    lw = batch.get("log_prob_w", None)
    ll = batch.get("log_prob_l", None)

    # If missing, return a benign scalar tensor.
    if lw is None or ll is None:
        if hasattr(model_output, "sum"):
            return model_output.sum() * 0.0
        for k in batch.keys():
            v = batch.get(k, None)
            if hasattr(v, "sum"):
                return v.sum() * 0.0
        return 0.0 * 0.0

    hyper = extra.get("hyperparams", {}) if isinstance(extra, dict) else {}

    def _get_hp(key, default):
        if isinstance(extra, dict) and (key in extra):
            return extra.get(key)
        return hyper.get(key, default)

    alpha = float(_get_hp("alpha", 1.0))
    beta = float(_get_hp("beta", 0.25))
    d_clip = float(_get_hp("d_clip", 30.0))
    z_clip = float(_get_hp("z_clip", 20.0))
    shift_clip = float(_get_hp("shift_clip", 3.0))
    d_eff_clip = float(_get_hp("d_eff_clip", 30.0))
    per_clip = float(_get_hp("per_clip", 5.0))

    # Objective delta signal: prefer delta_z; otherwise use common aliases or derive from costs.
    dz = batch.get("delta_z", batch.get("cost_gap", batch.get("delta_cost", None)))
    if dz is None:
        ca = batch.get("cost_a", None)
        cb = batch.get("cost_b", None)
        if ca is not None and cb is not None:
            dz = ca - cb
        else:
            dz = lw * 0.0

    d = ops.clamp(lw - ll, -d_clip, d_clip)
    dzc = ops.clamp(dz, -z_clip, z_clip)
    shift = ops.clamp(beta * dzc, -shift_clip, shift_clip)
    d_eff = ops.clamp(d + shift, -d_eff_clip, d_eff_clip)

    per = -ops.logsigmoid(alpha * d_eff)
    per = ops.clamp(per, 0.0, per_clip)
    return per.mean()

def generated_loss(batch, model_output, extra):
    lw = batch["log_prob_w"]
    ll = batch["log_prob_l"]
    dz = batch["delta_z"]
    base_weight = batch.get("weight", None)

    ex = extra if isinstance(extra, dict) else {}
    hyper = ex.get("hyperparams", {}) if isinstance(ex.get("hyperparams", {}), dict) else {}

    def _get_float(key, default):
        v = ex.get(key, None)
        if v is None:
            v = hyper.get(key, default)
        try:
            return float(v)
        except Exception:
            return float(default)

    alpha = _get_float("alpha", 1.0)
    beta = _get_float("beta", 0.25)
    mix = _get_float("mix", 0.6)

    d_clip = _get_float("d_clip", 30.0)
    z_clip = _get_float("z_clip", 20.0)
    shift_clip = _get_float("shift_clip", 3.0)
    d_eff_clip = _get_float("d_eff_clip", 30.0)
    per_clip = _get_float("per_clip", 5.0)
    w_clip = _get_float("w_clip", 10.0)

    # Clamp scalar in Python to avoid ops.clamp(float, ...)
    if mix < 0.0:
        mix = 0.0
    elif mix > 1.0:
        mix = 1.0

    d = ops.clamp(lw - ll, -d_clip, d_clip)
    dzc = ops.clamp(dz, -z_clip, z_clip)
    shift = ops.clamp(beta * dzc, -shift_clip, shift_clip)
    d_eff = ops.clamp(d + shift, -d_eff_clip, d_eff_clip)

    base = -ops.logsigmoid(alpha * d_eff)
    aux = ops.softplus(-alpha * d_eff)
    per = mix * base + (1.0 - mix) * aux
    per = ops.clamp(per, 0.0, per_clip)

    if base_weight is not None:
        bw = ops.clamp(base_weight, 0.0, w_clip)
        per = per * bw

    return per.mean()
